module mn_instruction_fifo (
    input wire clk, reset,
    input wire [127:0] in_data,
    input wire in_valid,
    output wire in_ready,
    output wire [127:0] out_data,
    output wire out_valid,
    input wire out_ready,
    output reg [2:0] count
);
    // Four tiny slots are explicit registers: avoid asynchronous array-read
    // inference into synchronous BRAM and its tool-generated bypass path.
    wire [127:0] words [0:3];
    reg [1:0] wr_ptr, rd_ptr;
    wire push=in_valid && in_ready;
    wire pop=out_valid && out_ready;
    assign in_ready=count<4;
    assign out_valid=count!=0;
    assign out_data=words[rd_ptr];
    genvar slot;
    generate for(slot=0;slot<4;slot=slot+1) begin: slots
        reg [127:0] storage;
        assign words[slot]=storage;
        always @(posedge clk)
            if(!reset && push && wr_ptr==slot) storage<=in_data;
    end endgenerate
    always @(posedge clk) begin
        if (reset) begin count<=0; wr_ptr<=0; rd_ptr<=0; end
        else begin
            if (push) wr_ptr<=wr_ptr+1'b1;
            if (pop) rd_ptr<=rd_ptr+1'b1;
            case ({push,pop})
                2'b10: count<=count+1'b1;
                2'b01: count<=count-1'b1;
                default: ;
            endcase
        end
    end
endmodule
